package com.bank.risk.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Sorts a queue of risk levels (0=low, 1=medium, 2=high) in one pass.
public class RiskQueueSorter {
    private static final Logger log = Logger.getLogger(RiskQueueSorter.class.getName());

    public void sortByRisk(int[] risks) {
        if (risks == null || risks.length < 2) return;
        int low = 0;
        int mid = 0;
        int high = risks.length - 1;

        while (mid <= high) {
            if (risks[mid] == 0) {            // low → front
                swap(risks, low, mid);
                low++;
                mid++;
            } else if (risks[mid] == 2) {     // high → back
                swap(risks, mid, high);
                high--;                       // do NOT advance mid here
            } else {                          // medium → stays
                mid++;
            }
        }
        log.info(() -> "Risk-sorted queue: " + Arrays.toString(risks));
    }

    private void swap(int[] a, int i, int j) {
        if (i == j) return;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}
