package com.bank.risk;

import com.bank.risk.service.RiskQueueSorter;
import java.util.Arrays;
import java.util.logging.Logger;

public class RiskQueueDemo {
    private static final Logger log = Logger.getLogger(RiskQueueDemo.class.getName());

    public static void main(String[] args) {
        // 0 = low risk, 1 = medium risk, 2 = high risk.
        int[] risks = {2, 0, 2, 1, 1, 0};
        log.info(() -> "Before: " + Arrays.toString(risks));

        RiskQueueSorter sorter = new RiskQueueSorter();
        sorter.sortByRisk(risks);

        log.info(() -> "After:  " + Arrays.toString(risks));
    }
}
